const request = $input.first().json;
const headers = $input.first().json.headers || {};

// Extract API key from header
const apiKey = headers['x-api-key'] || headers['X-API-Key'] || headers['authorization']?.replace('Bearer ', '');

if (!apiKey) {
  return [{ json: { authenticated: false, error: 'Missing API key. Include X-API-Key header.' } }];
}

return [{ json: { ...request, api_key: apiKey, authenticated: null } }];

const client = $input.first().json;
const originalRequest = $node['Webhook v2 - Contact Sync'].json;

// Check contact limit
if (client.current_contacts >= client.max_contacts) {
  return [{ json: { 
    authenticated: true, 
    authorized: false, 
    error: `Contact limit reached (${client.current_contacts}/${client.max_contacts})`,
    client_id: client.client_id
  }}];
}

// Merge client context with request data
return [{ json: {
  authenticated: true,
  authorized: true,
  client_id: client.client_id,
  client_code: client.client_code,
  company_name: client.company_name,
  plan_type: client.plan_type,
  // Original contact data
  email: originalRequest.body?.email || originalRequest.email,
  first_name: originalRequest.body?.first_name || originalRequest.first_name,
  last_name: originalRequest.body?.last_name || originalRequest.last_name,
  company: originalRequest.body?.company || originalRequest.company,
  phone: originalRequest.body?.phone || originalRequest.phone,
  job_title: originalRequest.body?.job_title || originalRequest.job_title,
  source: originalRequest.body?.source || originalRequest.source || 'api',
  tags: originalRequest.body?.tags || originalRequest.tags || [],
  custom_fields: originalRequest.body?.custom_fields || originalRequest.custom_fields || {}
}}];
